import 'package:test/test.dart';
import 'package:test_descriptor/test_descriptor.dart' as d;

void main() {
  test('file verification', () async {
    await d.dir('parent', [
      d.file('sibling.txt', 'hello world'),
      d.dir('child', [d.file('item.txt', 'item-content')])
    ]).create();

    await d.dir('parent', [
      d.file('sibling.txt', 'hello world')
    ]).validate();
  });
}
